#!/opt/anaconda3/bin/python3
"""Separate actual expert supplement: inherited v2 claim interface in v3.
Preserves initial/final reviews, all code/evidence, canonical bytes. No checker,
producer-private expectations or other reviewer verdicts read. Public discrepancy
guidance disclosed; own literal interpretation and actual metadata recomputation.
"""
import collections,datetime,json,pathlib,runpy,sys
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'reviews/expert';V=runpy.run_path(str(OUT/'review_belief_gap_v3.py'));sha,canon,equal=V['sha'],V['canon'],V['equal'];ROLE=V['ROLE']
NAMES={'same_prefix_empty_nonempty_counterfactual','contradiction_equals_mixed_outcomes'}
CAND_SHA='7284cb67509120efdc0f234f4bff026588f4926e5a72e0675eff7421cdf6a90c';OLD_SHA='c3d216ca74f3d332aa70bd25de21ea934c4e014e4f5934c24dfa90c8612cac0f'
def main():
 frozen_names=['belief-gap-v3.first_judgments.jsonl','belief-gap-v3.jsonl','review_belief_gap_v3.py','compare_belief_gap_v3.py','inspect_belief_gap_v3.py','finalize_belief_gap_v3.py','belief-gap-v3.input_only_predictions.json','belief-gap-v3.post_freeze_comparison.json','belief-gap-v3.semantic_quality_evidence.json','semantic_inspection_belief_gap_v3.md','belief-gap-v3.completed_execution.json']
 preserved={n:{'sha256':sha((OUT/n).read_bytes()),'length':(OUT/n).stat().st_size} for n in frozen_names}
 assert preserved['belief-gap-v3.first_judgments.jsonl']['sha256']==preserved['belief-gap-v3.jsonl']['sha256']==OLD_SHA
 docs=V['bindings']();v2=(ROOT/'schemas/BELIEF_CONTROL_PROPERTIES_REVISION_V2.md').read_text().splitlines();v3=(ROOT/'schemas/BELIEF_CONTROL_PROPERTIES_REVISION_V3.md').read_text().splitlines()
 assert 'Supplied E/G and F/H claims use `corpus_variant` with actual same-family pair IDs' in v2[41]
 assert 'amendments below take precedence for v3 grouping only' in v3[2]
 assert 'Retain original/v2 canonical fields' in v3[51]
 assert v3[41].startswith('| New family control') and 'pair-specific evidence may include actual two-element `pair_sample_ids`' in v3[47]
 candidate=ROOT/'data/RBM-001/candidate_renderings/belief-gap-v3.jsonl';raw=candidate.read_bytes();assert sha(raw)==CAND_SHA
 rows=[json.loads(l) for l in raw.splitlines()];assert len(rows)==3456
 preds=json.loads((OUT/'belief-gap-v3.input_only_predictions.json').read_text());by_pred={r['sample_id']:r for r in preds['records']}
 lookup={(r['source_family_key'],r['controlled_context'],r['auxiliary_scalar_variant'],r['schedule_index'],r['renderer']):r for r in rows};assert len(lookup)==3456
 witnesses=[];w_by_family=collections.defaultdict(list)
 for row in rows:
  if row['controlled_context'] not in 'EF':continue
  c=row['controlled_context'];other=lookup[(row['source_family_key'],{'E':'G','F':'H'}[c],row['auxiliary_scalar_variant'],row['schedule_index'],row['renderer'])]
  a,b=row['semantic_task'],other['semantic_task'];ap,bp=by_pred[row['sample_id']],by_pred[other['sample_id']]
  assert row['record_hash']==ap['record_hash'] and other['record_hash']==bp['record_hash']
  at,pa=V['solve'](a);bt,pb=V['solve'](b);assert equal(at,ap['facts']['expected']) and equal(bt,bp['facts']['expected'])
  changes=[i for i,(x,y) in enumerate(zip(a['observations'],b['observations'])) if not equal(x,y)]
  okay=equal(a['worlds'],b['worlds']) and equal(a['queries'],b['queries']) and len(a['observations'])==len(b['observations']) and [o['fact'] for o in a['observations']]==[o['fact'] for o in b['observations']] and equal(a['observations'][0],b['observations'][0]) and equal(pa[1],pb[1]) and changes==[1] and a['observations'][1]['fact']==b['observations'][1]['fact'] and not at['surviving_worlds'] and bool(bt['surviving_worlds'])
  assert okay
  witness={'source_family_key':row['source_family_key'],'auxiliary_scalar_variant':row['auxiliary_scalar_variant'],'schedule_index':row['schedule_index'],'renderer':row['renderer'],'observation_length':len(a['observations']),'pair_sample_ids':[row['sample_id'],other['sample_id']],'pair_record_hashes':[row['record_hash'],other['record_hash']],'actual_relationships':sorted(NAMES),'pass':okay,'actual_changed_equals_index':1,'same_first_prefix_ids':pa[1],'left_prefix_ids':pa,'right_prefix_ids':pb,'left_expected':at,'right_expected':bt,'own_execution_id':ROLE}
  witnesses.append(witness);w_by_family[row['source_family_key']].append(witness)
 assert len(witnesses)==864 and {p['observation_length'] for p in witnesses}=={2,3}
 results=[];examples=[];missing=collections.Counter();claims_total=0
 for r in rows:
  issues=[];claims=[c for c in r['family_control_claims'] if c.get('name',c.get('property')) in NAMES]
  assert {c.get('name',c.get('property')) for c in claims}==NAMES
  for c in claims:
   claims_total+=1;name=c.get('name',c.get('property'));valid_pair=isinstance(c.get('pair_sample_ids'),list) and len(c['pair_sample_ids'])==2 and len(set(c['pair_sample_ids']))==2
   pointer=isinstance(c.get('evidence_manifest'),str) and bool(c['evidence_manifest'])
   if c['scope']=='corpus_variant' and not valid_pair:
    missing[name]+=1;issues.append({'category':'missing_required_inherited_corpus_pair_ids','severity':'high','evidence':f"Actual {name} corpus_variant claim contains keys {sorted(c)} and no pair_sample_ids. V2 line42 expressly requires actual same-family pair IDs and length-specific pair evidence. V3 lines3/52 retain v2 fields; optional pair wording under New family control does not explicitly waive inherited requirements. Actual semantic pairs independently pass, but do not populate missing candidate metadata.",'fix':'Create a fresh generator version and immutable candidate containing exact same-family pair_sample_ids for both inherited controls and a length-specific evidence manifest/control entry, then review new hashes. Preserve existing candidate and original first/final receipts.'})
   if c['scope']=='corpus_variant' and not pointer:issues.append({'category':'missing_required_inherited_evidence_pointer','severity':'high','evidence':name+' has no evidence_manifest','fix':'Fresh candidate with relative length-specific pair evidence pointer.'})
  assert len(issues)==2
  pr=by_pred[r['sample_id']];old=next((w for w in w_by_family[r['source_family_key']] if w['observation_length']==len(r['semantic_task']['observations']) and w['auxiliary_scalar_variant']==r['auxiliary_scalar_variant'] and w['schedule_index']==r['schedule_index'] and w['renderer']==r['renderer']),None);assert old
  results.append({'receipt_id':'expert-belief-gap-v3-interface-supplement-'+sha(canon([r['sample_id'],r['record_hash'],ROLE]).encode())[:24],'sample_id':r['sample_id'],'record_hash':r['record_hash'],'reviewer_role':'expert_reviewer','reviewer_execution_id':ROLE,'review_status':'REVISE','decision':'REVISE','scores':{'semantic_correctness':5,'target_correctness':5,'instruction_clarity':5,'reasoning_validity':5,'generalization_value':3,'difficulty_quality':3 if r['controlled_context'] in 'DH' else 4,'diversity':3,'shortcut_resistance':3},'critical_defects':['required_inherited_control_pair_ids_absent'],'issues':issues,'confidence':0.98,'review_method':'Separate guided post-completion public-interface audit; actual canonical claims inspected for every row, required existing same-table semantic relationships independently reconstructed with own solver and exact hash joins. No other private verdict or checker source read.','original_frozen_first_final_sha256':OLD_SHA,'evidence':{'candidate_sha256':CAND_SHA,'original_prediction_sha256':preserved['belief-gap-v3.input_only_predictions.json']['sha256'],'public_v2_sha256':docs['schemas/BELIEF_CONTROL_PROPERTIES_REVISION_V2.md']['sha256'],'public_v3_sha256':docs['schemas/BELIEF_CONTROL_PROPERTIES_REVISION_V3.md']['sha256'],'actual_inherited_claims':claims,'independently_reconstructed_length_specific_pair':{'pair_sample_ids':old['pair_sample_ids'],'pair_record_hashes':old['pair_record_hashes'],'observation_length':old['observation_length'],'semantic_pass':True},'no_target_defect':True,'actual_metadata_defect':True}})
  if r['schedule_index']==0 and r['renderer']=='forward' and r['controlled_context'] in 'AEFGH':examples.append({'sample_id':r['sample_id'],'record_hash':r['record_hash'],'context':r['controlled_context'],'variant':r['auxiliary_scalar_variant'],'actual_inherited_claims':claims,'own_semantic_pair':old['pair_sample_ids'],'observation_length':old['observation_length']})
 now=datetime.datetime.now(datetime.timezone.utc).isoformat();source_sha=sha(pathlib.Path(__file__).read_bytes())
 report={'report_type':'FROZEN_V3_INHERITED_PUBLIC_INTERFACE_SUPPLEMENT','actual_author':ROLE,'created_utc':now,'mode':'Root-reported machine discrepancy prompted this separate guided audit. No supplied checker result accepted as evidence; own public-text interpretation and canonical metadata enumeration. Original first/final review unchanged.','candidate_sha256':CAND_SHA,'source_sha256':source_sha,'public_source_bindings':docs,'original_frozen_artifacts':preserved,'interpretation':'V2 line42 remains binding on its two inherited controls. V3 line48 relaxes pair-specific encoding in its New family control section for the three new identifiers and allows aggregate crossing claims. V3 lines3 and52 retain v2 fields and specialize grouping; no explicit inherited-control waiver exists. General optional shape permits omission for some identifiers, while the v2 specialized semantic identifier rule still requires pair IDs.','ambiguity_boundary':'Reading isolated v3 line48 as a global waiver is possible if its heading/context is ignored. That broad reading conflicts with explicit inherited retention. Future public clarifying prose may remove ambiguity, but must not retrospectively alter frozen design/candidate/review facts. The existing deterministic metadata requirement can be satisfied directly in a fresh candidate without changing task semantics.','finding':{'affected_records':len(rows),'affected_claims':claims_total,'missing_pair_ids_by_identifier':dict(missing),'target_or_semantic_pair_defects':0,'independently_reconstructed_inherited_pairs':len(witnesses),'pair_length_distribution':dict(collections.Counter(str(w['observation_length']) for w in witnesses)),'supplemental_decisions':{'REVISE':len(results)},'severity':'high required metadata/release-blocking; no filtering target error'},'initial_review_omission':'Own initial audit independently reconstructed both required relationships but reused a metadata validator that treated pair_sample_ids as generally optional. I failed to enforce v2 line42 on the inherited identifiers. The frozen initial ACCEPT receipts remain historical evidence; this supplement changes the current expert recommendation for these exact hashes to REVISE.','evidence_pointer_scope':'The actual candidate has a nonempty shared relative evidence_manifest and generic family/variant control_id. This supplement does not read producer manifests/private expectations. An uninspected pointer cannot establish length-specific evidence, and even a rich external manifest would not satisfy the separately required absent candidate pair IDs. Own exact supports/pairs are recorded here.','substantive_sample_evidence':examples,'independent_inherited_pair_witnesses':witnesses,'recommended_next_step':'Fresh generator/version and immutable batch with inherited same-table E/G or F/H pair IDs at exact scalar variant/schedule/renderer, actual length-specific pair evidence, and recomputed complete candidate record hashes. The same visible tasks/targets may be retained; new metadata bytes require new exact-bound review. Preserve v3 canonical and all initial receipts unchanged.','no_release_adjudication_approval':True}
 reportpath=OUT/'belief-gap-v3.inherited_claim_interface_supplement.json';rh=V['save'](reportpath,report)
 raw_receipts=('\n'.join(canon(r) for r in results)+'\n').encode();first=OUT/'belief-gap-v3.inherited_claim_interface_supplement.first_judgments.jsonl';final=OUT/'belief-gap-v3.inherited_claim_interface_supplement.jsonl';assert not first.exists() and not final.exists();first.write_bytes(raw_receipts);final.write_bytes(raw_receipts)
 mdpath=OUT/'semantic_inspection_belief_gap_v3_inherited_claim_interface_supplement.md';assert not mdpath.exists();mdpath.write_text(f'''# Frozen expert supplement: inherited v3 claim interface\n\nActual author `{ROLE}`. Candidate SHA `{CAND_SHA}`. Original first/final receipts SHA `{OLD_SHA}` remain unchanged. This is a root-discrepancy-guided public-interface audit, not a fresh blind semantic review. No checker, private other review verdict, producer-private expectations or producer manifest was read.\n\nAll3,456 rows lack actual `pair_sample_ids` on both inherited `same_prefix_empty_nonempty_counterfactual` and `contradiction_equals_mixed_outcomes` corpus claims:6,912 deficient claims. Their actual semantics are correct: my fresh execution reconstructs864 same-table pairs,432 at each observation length, with identical first-prefix IDs, only equals[1] changed, and opposite final statuses. Correct pair existence does not provide the omitted required candidate fields.\n\nV2 line42 expressly says supplied E/G and F/H claims use corpus scope with actual same-family pair IDs and length-specific pair evidence. V3 line48 says pair-specific evidence may include pair IDs, but appears in the section for the three **new** family controls; its aggregate crossing encoding applies to that new crossing claim. V3 line3 says amendments take precedence for grouping only, and line52 retains original/v2 fields. I find no explicit waiver of the inherited requirement. Optional fields in the general closed object shape do not prevent a particular named relationship from imposing a required field.\n\nThe initial expert validator treated IDs as generally optional and did not enforce this specialized v2 rule. That was my review omission. Preserve the initial ACCEPT artifacts as frozen history; the current supplemental recommendation is3,456 REVISE for these exact hashes. Filtering targets, row properties, paired support truths and prior residual correlation measurements remain unaffected.\n\nThe candidate shared manifest pointer and generic control ID cannot stand in for required absent pair IDs. I did not inspect that producer pointer; even if it described lengths, the separate conjunctive pair-ID requirement is unsatisfied. Actual independently reconstructed, length-specific pairs and sample hashes are in the companion JSON.\n\nRecommend a fresh generator version and immutable candidate containing exact inherited same-table pair IDs and length-specific evidence entries, with all record hashes recomputed. Keep the old candidate and all old reviews. No release/adjudication approval is issued.\n\nReport SHA `{rh}`; supplemental receipt SHA `{sha(raw_receipts)}`.\n''')
 assert all(sha((OUT/n).read_bytes())==v['sha256'] for n,v in preserved.items()) and sha(candidate.read_bytes())==CAND_SHA
 execution={'report_type':'ACTUAL_SUPPLEMENT_EXECUTION_FREEZE','actual_author':ROLE,'created_utc':now,'python_executable':sys.executable,'actual_argv':sys.argv,'exit_code':0,'source_sha256':source_sha,'report_sha256':rh,'first_final_receipts_sha256':sha(raw_receipts),'first_final_byte_equal':True,'decisions':{'REVISE':len(results)},'record_count':len(rows),'exact_candidate_hash_joins':True,'old_artifacts_unchanged':True,'canonical_unchanged':True,'inspection_sha256':sha(mdpath.read_bytes()),'public_bindings':docs,'no_other_private_verdict_checker_or_producer_manifest_read':True,'prior_preoutput_interruption_evidence':'belief-gap-v3.inherited_claim_interface_supplement.attempt1_interruption.json','no_release_approval':True,'filesystem_write_freeze_after_execution':True}
 eh=V['save'](OUT/'belief-gap-v3.inherited_claim_interface_supplement.execution.json',execution)
 print(canon({'affected_records':len(rows),'affected_claims':claims_total,'pair_semantic_passes':len(witnesses),'decision':'REVISE','report_sha256':rh,'receipt_sha256':sha(raw_receipts),'execution_sha256':eh,'old_artifacts_unchanged':True}))
if __name__=='__main__':main()
